CREATE OR REPLACE FUNCTION protect_published_handbook() RETURNS trigger AS $$
BEGIN
 IF OLD.status='published' THEN RAISE EXCEPTION 'Published handbook versions are immutable; create a new version.'; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER handbook_immutable BEFORE UPDATE OR DELETE ON handbook_versions FOR EACH ROW EXECUTE FUNCTION protect_published_handbook();
