INSERT INTO handbook_versions(document_id,version,effective_on,content,review,content_hash,updated_by) VALUES ('academy-2027',1,'2027-01-01','{"title":"2027 Parent & Player Handbook","sections":[{"title":"Welcome and our commitment","body":"Welcome to Prospects Sports Academy. Since 2008, Prospects has brought baseball and softball families together around preparation, effort, accountability and player development. Ownership commits to communicating published season expectations, providing the agreed services, respecting athlete safety, and offering a clear path for concerns. Families commit to preparation, respectful conduct and their signed season obligations."},{"title":"How this handbook works","body":"Organization standards set minimum requirements for safety, conduct, communication and operations. Your sport supplement explains sport-specific considerations. Your approved team addendum states the coach’s playing-time philosophy, practices, tournament expectations and evaluation approach. Your separately accepted financial agreement controls actual fees, due dates and financial terms. A handbook revision cannot silently amend an existing signed agreement."},{"title":"Development and competition","body":"Development includes movement quality, skill execution, decision-making, effort, confidence and consistency. Wins, statistics and velocity alone do not measure progress. Developmental teams emphasize meaningful participation, positional exploration and long-term growth without promising equal playing time. Competitive teams also consider performance, readiness and game strategy. Coaches establish the designation and expectations before financial enrollment. Fees do not purchase a particular position, lineup spot or amount of playing time."},{"title":"Development feedback and training","body":"Every enrolled team athlete receives at least one documented in-season development update and a final evaluation. A preseason baseline is recommended. Coaches use the existing development platform for assigned goals, drills and progress when applicable; assessments are not automatically completed by enrollment. Feedback distinguishes observed measurements from estimates and coaching judgments. Age, experience, recovery and medical restrictions guide assignments. Individual lessons and optional services are included only when specifically stated in the published offer."},{"title":"Attendance and preparation","body":"Give at least 48 hours’ notice for a planned practice absence and 14 calendar days for a planned tournament absence. Report extended absences as soon as known, preferably 30 days ahead. Report illness, injury or emergencies as soon as reasonably possible. Notify the coach before late arrival or early departure. Record availability and contact the coach directly unless the team addendum expressly accepts the account notice as sufficient. Notice does not automatically excuse an absence. Legitimate medical emergencies and appropriate medical restrictions are not disciplinary violations."},{"title":"Conduct and discipline","body":"Players, parents and coaches must treat teammates, opponents and officials respectfully. Bullying, hazing, harassment, discrimination, threats, physical aggression, equipment abuse and abusive coaching are prohibited. Ordinary discipline progresses through a verbal warning, written warning, temporary restriction and possible removal. Serious safety concerns may require immediate action. Before permanent removal for nonemergency misconduct, leadership reviews the facts, gives the family a reasonable opportunity to respond and provides a written decision. Suspected abuse is escalated promptly outside the ordinary discipline process. Retaliation for reporting is prohibited."},{"title":"Communication and concerns","body":"Contact the head coach first for routine schedule, development or team concerns. Coaches should acknowledge nonurgent messages within 48 hours. Wait until the following day before raising an emotionally charged nonurgent game disagreement. Unresolved routine concerns may go to the authorized sport coordinator, then ownership. Financial matters go directly to Steve or Nolan. Safety concerns, suspected abuse, discrimination and medical emergencies bypass the cooling-off period and coach-first requirement."},{"title":"Season fees and optional services","body":"Before acceptance, your account shows the owner-published team fee, included services, installment amounts and due dates. The usual new-season schedule is 70%, 15%, 15%, subject to the actual published plan and any retained agreement. The Team & Development Program amount comes from the owner-approved team configuration; this handbook sets no dollar amount and changes no pricing formula. Individual facility access is an optional selection with separate disclosed benefits and terms. Do not assume team enrollment includes unlimited cage use, private lessons or every membership product. Only verified payments and approved ledger credits affect the account."},{"title":"Withdrawal, injury and cancellation","body":"The signed season financial agreement controls refunds, withdrawals and outstanding obligations. Injury, voluntary withdrawal, playing-time dissatisfaction and scheduling conflicts do not automatically cancel that agreement. Medical restrictions remain respected regardless of payment status. Legally required remedies and approved contractual exceptions are preserved. If Prospects cancels a team or cannot provide the agreed season, ownership reviews delivered services, documented committed costs and unspent or recoverable funds, supplies an itemized determination, and honors the signed contract and applicable rights. Team cancellation is not treated as a family’s voluntary withdrawal."},{"title":"Replacement players and financial adjustments","body":"Ownership must approve replacement-player offers and any adjustment to a departing family’s obligation. The review distinguishes delivered services, nonrecoverable commitments, recoverable expenses and new player-specific costs, and checks for duplicate recovery of the same expense. Coaches and coordinators cannot promise refunds, waive balances or change signed terms. Approved amendments and credits are recorded separately; the original agreement remains preserved."},{"title":"Fundraising and assistance","body":"Prospects does not currently offer organization-funded scholarships, hardship exemptions or alternative payment arrangements. Approved fundraising may reduce outstanding obligations. Individual credits follow fundraiser terms and donor restrictions; team-wide net proceeds follow the allocation disclosed in advance. Expenses, proceeds and credits must be recorded through the authorized ledger. Extra proceeds do not automatically become cash payouts. Families can review their own financial account; other families’ balances and organization budgets remain private."},{"title":"Athlete protection","body":"Adults with regular athlete access must meet applicable screening and athlete-protection training requirements before service. Instruction must be observable and interruptible. Electronic communication with minor athletes includes a parent/guardian or another authorized adult under the safety policy. Inappropriate private interactions, sexual misconduct, physical punishment and abusive coaching are prohibited. Report suspected abuse promptly to the appropriate authorities; an internal report does not replace a required external report. Do not wait for a coach or office reply in an emergency."},{"title":"Safety contacts and escalation","body":"Steve McCutcheon is the initial organization safety contact through the academy’s published contact information. Concerns involving Steve or his team decisions should be directed to Nolan McCutcheon through ownership, or directly to the appropriate external authority. A safety concern is not routed back only to the subject of the complaint. The office must confirm a reachable alternate and emergency-response plan before enabling enrollment signatures. Call emergency services for an immediate danger. Safety reports and medical records are restricted and are not ordinary team announcements."},{"title":"Medical information and return to activity","body":"Guardians provide current emergency contacts and relevant medical alerts securely. Coaches respect restrictions and activate the team emergency plan when necessary. A suspected concussion requires removal from activity and the applicable medical clearance before return. Stop throwing or other activity that causes pain and seek appropriate evaluation. Coaches follow the adopted heat, hydration, severe-weather and equipment protocols. The handbook does not diagnose an injury, provide clearance or replace individualized medical advice. Emergency authorization and medical consent are separately reviewed documents."},{"title":"Facility and equipment","body":"Use the Prospects Sports Facility only for authorized bookings or scheduled team activity. Follow cage, pitching-machine, protective-screen and helmet instructions. Maintain appropriate adult supervision, keep spectators and siblings in designated areas, return equipment and keep exits clear. Report damaged equipment or hazards promptly. Every participating athlete needs a current facility waiver. Booking availability and the current catalog determine optional access. Cage, lesson and membership cancellation terms are distinct from seasonal team withdrawal terms; review the applicable agreement for each purchase."},{"title":"Travel and supervision","body":"Parents arrange transportation, lodging, meals and supervision outside official team activities unless an explicit arrangement is accepted. When another adult supervises, the legal guardian authorizes the arrangement and identifies an adult at least 18 years old to the coach. Coaches are not automatically responsible for hotels, transportation or time between games. During official practices, games, warmups and coach-directed activities, applicable team supervision duties continue. Private arrangements do not transfer legal custody or remove athlete-protection requirements."},{"title":"Privacy, media and technology","body":"Use your existing family account for your own athletes and protect sign-in credentials. Medical information, safety concerns and private development records do not belong in public rosters or team chats. Public roster identity, photos, recruiting and media uses require their applicable separate permissions. Optional media consent is separate from enrollment, may be declined without blocking participation and may be withdrawn for future use. Withdraw through the account’s existing consent controls. Only deployed and assigned development features are represented as available."},{"title":"First 30 days","body":"Activate the correct guardian account, review your team packet and published financial offer, complete required signatures and emergency information, and verify the deposit. Submit uniform sizes, meet the coach, review the schedule and facility rules, and establish development goals. The team checklist records orientation and baseline assessment only when actually completed. A family can still access its documents, payment steps and safety contact while enrollment requirements are incomplete."},{"title":"Versions and acknowledgment","body":"The account preserves the exact handbook, sport supplement, team standards and financial terms accepted by the guardian, together with the signer and date. New material contractual terms require a new agreement where applicable. Safety and administrative updates have effective dates and documented communication. A payment does not substitute for signing; a signature does not prove payment. Optional consent is never bundled into required agreement acceptance."}]}'::jsonb,'{"legalReviewer":"","legalReviewedOn":"","insuranceReviewer":"","insuranceReviewedOn":"","reviewReference":""}'::jsonb,'3d49aa28f8e971b9a509634ac902144a2b8c781dd2423c545542b563ac9234b6','system:2027-framework');
INSERT INTO handbook_versions(document_id,version,effective_on,content,review,content_hash,updated_by) VALUES ('baseball-2027',1,'2027-01-01','{"title":"2027 Baseball Supplement","sections":[{"title":"Baseball development","body":"Coaches adapt hitting, fielding, baserunning, catching, throwing and situational instruction to age, experience and the team’s developmental or competitive designation. Younger athletes should have meaningful opportunities to learn and explore positions without a promise of equal playing time. Individual goals and reassessments use the existing development record."},{"title":"Throwing and pitching","body":"Follow the applicable tournament, league and adopted age-specific pitching and rest rules. Include outside-team throwing when discussing workload. Report arm pain immediately, stop painful activity, and respect medical restrictions. No universal pitch-count number is established by this handbook; approved current rules and individualized medical advice govern."},{"title":"Competition and equipment","body":"The coach confirms age eligibility, field dimensions, bat/equipment requirements, roster rules and guest-player eligibility for each competition. Published schedules remain subject to organizer changes. Catchers and field players use the required protective equipment. The team addendum establishes expectations before enrollment."}]}'::jsonb,'{"legalReviewer":"","legalReviewedOn":"","insuranceReviewer":"","insuranceReviewedOn":"","reviewReference":""}'::jsonb,'80582aca20fdf60d96a3a3907d1f84d9b86bf8026c9eda82648023f3c3a65e17','system:2027-framework');
INSERT INTO handbook_versions(document_id,version,effective_on,content,review,content_hash,updated_by) VALUES ('softball-2027',1,'2027-01-01','{"title":"2027 Softball Supplement","sections":[{"title":"Softball development","body":"Coaches adapt fastpitch hitting, pitch recognition, bunting, slapping, fielding, baserunning, catching and situational instruction to athlete age and experience. Team designation and playing-time expectations are communicated before enrollment. Progress includes skill, decisions, confidence and consistency."},{"title":"Throwing and pitching","body":"Windmill pitching workload, recovery and arm care require softball-specific planning. Baseball pitching limits must not be automatically substituted for softball guidance. Coaches follow applicable governing rules and adopted medical/sports-science guidance, discuss outside-team workload, stop painful activity and honor medical restrictions."},{"title":"Competition and equipment","body":"The coach confirms division and roster eligibility, field dimensions, lead-off rules, protective equipment and competition requirements for each event. Position development includes softball-specific short-game defense, receiving, blocking and throwing. The approved team addendum establishes practice and tournament commitments."}]}'::jsonb,'{"legalReviewer":"","legalReviewedOn":"","insuranceReviewer":"","insuranceReviewedOn":"","reviewReference":""}'::jsonb,'0285ab0d9cab8b4186d31640fbd687cdf54e55119e84c1eb953a0f3ba96da02d','system:2027-framework');

    INSERT INTO _migrations (name) VALUES ('0105_handbook_versions.sql');
  END IF;
